/* From Uiverse.io by Efrain2112  - Tags: simple, blue, white, pattern */
.__UIV_SCOPE__ .container {
  width: 100%;
  height: 100%;
  --size: 80px; /* control the size */
  --color: #add8e6;

  background: linear-gradient(
      to bottom,
      transparent 0%,
      transparent 40%,
      #add8e6 41%,
      #add8e6 60%,
      transparent 61%,
      transparent 100%
    ),
    linear-gradient(
      45deg,
      #add8e6 25%,
      transparent 25%,
      transparent 50%,
      #add8e6 50%,
      #add8e6 75%,
      transparent 75%,
      transparent
    );
  background-size: var(--size) var(--size);
}
